TLM.f("Tempora/Nat05",{"officium":"Die Quinta Januarii","rule":["vide Sancti/01-01","Prefatio=Nat","Gloria"],"ruleInherited":["ex Sancti/12-25m3;","Gloria","Credo","Prefatio=Nat","Gloria","Credo","Prefatio=Nat","celebranda aut missa prima aut missa secunda aut missa tertia","no Ultima Evangelium"],"fallback":"Sancti/01-01","from":{"Introitus":"Sancti/01-01","Oratio":"Sancti/01-01","Lectio":"Sancti/01-01","Graduale":"Sancti/01-01","Evangelium":"Sancti/01-01","Offertorium":"Sancti/01-01","Secreta":"Sancti/01-01","Communio":"Sancti/01-01","Postcommunio":"Sancti/01-01"},"sections":{"Introitus":[{"k":"ref","la":"Isa 9:6"},{"k":"text","la":"Puer natus est nobis, et fílius datus est nobis: cujus impérium super húmerum ejus: et vocábitur nomen ejus magni consílii Angelus."},{"k":"ref","la":"Ps 97:1"},{"k":"text","la":"Cantáte Dómino cánticum novum, quia mirabília fecit."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Puer natus est nobis, et fílius datus est nobis: cujus impérium super húmerum ejus: et vocábitur nomen ejus magni consílii Angelus."}],"Oratio":[{"k":"text","la":"Deus, qui salútis ætérnæ, beátæ Maríæ virginitáte fecúnda, humáno generi præmia præstitísti: tríbue, quǽsumus; ut ipsam pro nobis intercédere sentiámus, per quam merúimus auctórem vitæ suscípere, Dóminum nostrum Jesum Christum, Fílium tuum:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beati Pauli Apóstoli ad Titum"},{"k":"ref","la":"Tit 2:11-15"},{"k":"text","la":"Caríssime: Appáruit grátia Dei Salvatóris nostri ómnibus homínibus, erúdiens nos, ut, abnegántes impietátem et sæculária desidéria, sóbrie et juste et pie vivámus in hoc sǽculo, exspectántes beátam spem et advéntum glóriæ magni Dei et Salvatóris nostri Jesu Christi: qui dedit semetípsum pro nobis: ut nos redímeret ab omni iniquitáte, et mundáret sibi pópulum acceptábilem, sectatórem bonórum óperum. Hæc lóquere et exhortáre: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 97:3; 97:2"},{"k":"text","la":"Vidérunt omnes fines terræ salutare Dei nostri: jubiláte Deo, omnis terra."},{"k":"text","la":"Notum fecit Dominus salutare suum: ante conspéctum géntium revelávit justitiam suam.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Heb 1:1-2"},{"k":"text","la":"Multifárie olim Deus loquens pátribus in Prophétis, novíssime diébus istis locútus est nobis in Fílio. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 2:21"},{"k":"text","la":"In illo témpore: Postquam consummáti sunt dies octo, ut circumciderétur Puer: vocátum est nomen ejus Jesus, quod vocátum est ab Angelo, priúsquam in útero conciperétur."}],"Offertorium":[{"k":"ref","la":"Ps 88:12; 88:15"},{"k":"text","la":"Tui sunt cœli et tua est terra: orbem terrárum et plenitúdinem ejus tu fundásti: justítia et judícium præparátio sedis tuæ."}],"Secreta":[{"k":"text","la":"Munéribus nostris, quǽsumus, Dómine, precibúsque suscéptis: et cœléstibus nos munda mystériis, et cleménter exáudi."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 97:3"},{"k":"text","la":"Vidérunt omnes fines terræ salutáre Dei nostri."}],"Postcommunio":[{"k":"text","la":"Hæc nos commúnio, Dómine, purget a crímine: et, intercedénte beáta Vírgine Dei Genetríce María, cœléstis remédii fáciat esse consórtes."},{"k":"macro","name":"Per eundem"}]},"hr":{"2556a7cf67c03224":{"t":"Iz 9, 6, Ps 97, 1\n(Iz 9, 6) Dijete nam se rodilo i Sin nam je darovan. Znak mu je vlasti na ramenu, a ime mu je Anđeo velikoga savjeta. (Ps 97, 1) Pjevajte Gospodinu novu pjesmu, jer učini divna djela.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 9, 6) Dijete nam se rodilo i Sin nam je darovan. Znak mu je vlasti na ramenu, a ime mu je Anđeo velikoga savjeta.","v":"∅ → filius; ∅ → filius"},"c79c33bb27747538":{"t":"<i>Pomolimo se</i>.\nBože, koji si plodnim djevičanstvom blažene Marije darovao ljudskom rodu dobra vječnog spasenja, podaj, molimo te, da osjetimo zagovor one po kojoj smo zavrijedili primiti početnika života, Gospodina našega Isusa Krista, Sina tvoga:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"b783e9397f6c6cf1":{"t":"Tit 2, 11-15\nČitanje Poslanice bl. Pavla apostola Titu. Predragi: milost Boga našega Spasitelja objavila se svim ljudima učeći nas, da se odrečemo bezbožnosti i svjetovnih želja i da živimo na ovom svijetu trijezno i pravedno i pobožno, očekujući blaženu nadu i slavni dolazak velikoga Boga i našeg Spasitelja Isusa Krista. On je samog sebe dao za nas, da nas otkupi od svakog bezakonja i da očisti za se izabrani narod koji revnuje oko dobrih djela. Ovo govori i potiči u našemu Gospodinu Isusu Kristu!"},"c69237c337a16131":{"t":"Ps 97, 3-4 i 2\nSvi krajevi zemlje vidješe spasenje Boga našega. Kličite Bogu, sve zemlje. Gospodin je objavio svoje spasenje, otkrio svoju pravdu pred licem naroda.\n\nHeb 1, 1-2\n<i>Aleluja</i>, <i>aleluja</i>.\nMnogo je puta nekoć govorio Bog ocima preko proroka, a ovih nam je dana napokon progovorio po Sinu. <i>Aleluja</i>."},"613f5280ca0f9775":{"t":"Lk 2, 21\nSlijedi sveto Evanđelje po Luki. U ono vrijeme, kad se navršilo osam dana da obrežu Dijete, dadu mu ime Isus, kao što ga je anđeo bio nazvao prije njegova začeća."},"1dcee0ba49089f56":{"t":"Ps 88, 12 i 15\nTvoja su nebesa, tvoja je zemlja, ti si stvorio zemaljski krug i sve što je na njemu. Pravda i pravo temelji su prijestolja tvoga."},"0741f87b36183013":{"t":"Primi, molimo, Gospodine, naše darove i molitve te nas nebeskim otajstvima očisti i milostivo usliši.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"46276ff06c5f858a":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine sveti Oče, svemogući i vječni Bože: jer je po tajni utjelovljene Riječi očima naše duše sinula nova svjetlost tvoga sjaja. Te dok tjelesnim očima spoznajemo Boga, on nas zanosi ljubavlju prema nevidljivim dobrima. I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"3497b8df953b1338":{"t":"Ps 97, 3\nSvi krajevi zemlje vidješe spasenje Boga našega."},"f3420e82111d9894":{"t":"<i>Pomolimo se</i>.\nOva Pričest, Gospodine, neka nas očisti od opačina i zagovorom blažene Djevice Bogorodice Marije neka nas učini dionicima nebeskog lijeka.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
